<template><section class="space-y-5 p-4 sm:p-6"><header><h1 class="text-2xl font-semibold text-gray-900 dark:text-white">Model health</h1><p class="mt-1 text-sm text-gray-500">Public quality and reliability signals for available models.</p></header><div class="grid gap-4 md:grid-cols-2 xl:grid-cols-3"><div v-for="model in models" :key="model.model_alias" class="rounded-lg border border-gray-200 bg-white p-4 dark:border-dark-700 dark:bg-dark-900"><div class="flex items-center justify-between"><h2 class="font-medium dark:text-white">{{ model.model_alias }}</h2><span class="text-xs text-gray-500">{{ model.health_state }}</span></div><p class="mt-4 text-sm text-gray-500">Samples {{ model.sample_count ?? 'n/a' }}</p><p class="mt-1 text-sm text-gray-500">P99 {{ model.p99_ms == null ? 'n/a' : `${model.p99_ms} ms` }}</p><p class="mt-1 text-sm text-gray-500">Error rate {{ model.error_rate == null ? 'n/a' : `${(model.error_rate * 100).toFixed(2)}%` }}</p></div></div><div v-if="!models.length" class="rounded-lg border border-dashed border-gray-300 p-8 text-center text-sm text-gray-500">No public model health data available</div></section></template><script setup lang="ts">import { onMounted, ref } from 'vue'; import { getModelHealth, type RadarPublicHealth } from '@/api/radar'; const models = ref<RadarPublicHealth[]>([]); onMounted(async () => { try { models.value = await getModelHealth() } catch { models.value = [] } });</script>
